int a[9][9];

int check_sudoku(int a[][9]) {
    int i, j, k;
    int b[9];
    // check rows
    i = 0;
    while (i < 9) {
        j = 0;
        while (j < 9) {
            b[j] = 0;
            j = j + 1;
        }
        j = 0;
        while (j < 9) {
            if (a[i][j]) {
                if (!b[a[i][j] - 1]) {
                    b[a[i][j] - 1] = 1;
                } else {
                    return 0;
                }
            }
            j = j + 1;
        }
        i = i + 1;
    }

    // check columns
    i = 0;
    while (i < 9) {
        j = 0;
        while (j < 9) {
            b[j] = 0;
            j = j + 1;
        }
        j = 0;
        while (j < 9) {
            if (a[j][i]) {
                if (!b[a[j][i] - 1]) {
                    b[a[j][i] - 1] = 1;
                } else {
                    return 0;
                }
            }
            j = j + 1;
        }
        i = i + 1;
    }

    // check 3x3 squares
    i = 0;
    while (i < 3) {
        j = 0;
        while (j < 3) {
            k = 0;
            while (k < 9) {
                b[k] = 0;
                k = k + 1;
            }
            k = 0;
            while (k < 3) {
                int l;
                l = 0;
                while (l < 3) {
                    int m;
                    m = a[i * 3 + k][j * 3 + l];
                    if (m) {
                        if (!b[m - 1]) {
                            b[m - 1] = 1;
                        } else {
                            return 0;
                        }
                    }
                    l = l + 1;
                }
                k = k + 1;
            }
            j = j + 1;
        }
        i = i + 1;
    }

    return 1;

}

int solve_sudoku() {
    int i, j, solve_i, solve_j, done = 1;
    i = 0;
    while (i < 9 && done) {
        j = 0;
        while (j < 9 && done) {
            if (a[i][j] == 0) {
                done = 0;
                solve_i = i;
                solve_j = j;
            }
            j = j + 1;
        }
        i = i + 1;
    }
    if (done) {
        return check_sudoku(a);
    }
    i = 1;
    while (i <= 9) {
        a[solve_i][solve_j] = i;
        if (check_sudoku(a)) {
            if (solve_sudoku()) {
                return 1;
            }
        }
        i = i + 1;
    }
    a[solve_i][solve_j] = 0;
    return 0;
}

int main() {

    int i = 0, j = 0;
    int solve = 0;
    while (i < 9) {
        j = 0;
        while (j < 9) {
            a[i][j] = read();
            if (a[i][j] < 0 || a[i][j] > 9) {
                write(0);
                return 0;
            } else if (a[i][j] == 0) {
                solve = 1;
            }
            j = j + 1;
        }
        i = i + 1;
    }

    if (solve) {
        if (solve_sudoku()) {
            i = 0;
            while (i < 9) {
                j = 0;
                while (j < 9) {
                    write(a[i][j]);
                    j = j + 1;
                }
                i = i + 1;
            }
        } else {
            write(0);
        }
    } else if (check_sudoku(a)) {
        write(1);
    } else {
        write(0);
    }

    return 0;
}

